from ui import *
def seg_loop(listname):
    on=tag('button','{{it.label}}',attrs=' type="button" aria-pressed="true" onClick="{{it.pick}}"',font=f"500 12.5px {MONO}",padding='6px 10px',min_height='32px',border='0',border_radius='3px',background='var(--surface)',color='var(--ink)',box_shadow='0 0 0 1px var(--line)',cursor='pointer')
    off=tag('button','{{it.label}}',attrs=' type="button" aria-pressed="false" onClick="{{it.pick}}"',font=f"500 12.5px {MONO}",padding='6px 10px',min_height='32px',border='0',border_radius='3px',background='transparent',color='var(--muted)',cursor='pointer')
    inner=f'<sc-for list="{{{{{listname}}}}}" as="it" hint-placeholder-count="3"><sc-if value="{{{{it.on}}}}" hint-placeholder-val="{{{{false}}}}">{on}</sc-if><sc-if value="{{{{it.off}}}}" hint-placeholder-val="{{{{true}}}}">{off}</sc-if></sc-for>'
    return div(inner,attrs=f' role="group" aria-label="{listname}"',display='inline-flex',gap='2px',padding='3px',background='var(--sunken)',border='1px solid var(--line)',border_radius='4px')
def toggle(lbl,flag,handler):
    on=tag('button',tag('span','',width='8px',height='8px',border_radius='2px',background='var(--accent-ink)',display='inline-block')+lbl,attrs=f' type="button" aria-pressed="true" onClick="{{{{{handler}}}}}"',font='600 12.5px Inter, sans-serif',display='inline-flex',align_items='center',gap='7px',padding='6px 10px',min_height='34px',border='1px solid var(--accent-ink)',border_radius='4px',background='var(--accent-subtle)',color='var(--ink)',cursor='pointer')
    off=tag('button',tag('span','',width='8px',height='8px',border_radius='2px',border='1px solid var(--muted)',display='inline-block')+lbl,attrs=f' type="button" aria-pressed="false" onClick="{{{{{handler}}}}}"',font='600 12.5px Inter, sans-serif',display='inline-flex',align_items='center',gap='7px',padding='6px 10px',min_height='34px',border='1px solid var(--line)',border_radius='4px',background='transparent',color='var(--muted)',cursor='pointer')
    return f'<sc-if value="{{{{{flag}}}}}" hint-placeholder-val="{{{{false}}}}">{on}</sc-if><sc-if value="{{{{not{flag[0].upper()+flag[1:]}}}}}" hint-placeholder-val="{{{{true}}}}">{off}</sc-if>'
def measure_overlay():
    cy='var(--accent-ink)'
    lab_=lambda t,**k: tag('span',t,font=f"500 11.5px {MONO}",color=cy,white_space='nowrap',position='absolute',**k)
    h=div(div('',position='absolute',left='0',top='0',width='9px',height='1px',background=cy)+div('',position='absolute',left='0',bottom='0',width='9px',height='1px',background=cy)+div('',position='absolute',left='4px',top='0',bottom='0',width='1px',background=cy)+lab_('{{heightLabel}}',left='15px',top='50%',transform='translateY(-50%)'),position='absolute',right='-26px',top='0',bottom='0',width='9px')
    pad=div(div('',position='absolute',left='0',right='0',top='4px',height='1px',background=cy)+div('',position='absolute',left='0',top='0',width='1px',height='9px',background=cy)+div('',position='absolute',right='0',top='0',width='1px',height='9px',background=cy)+lab_('{{padLabel}}',left='50%',top='14px',transform='translateX(-50%)'),position='absolute',left='0',width='18px',bottom='-28px',height='9px')
    rad=lab_('radius {{radiusLabel}}',left='0',top='-24px')
    box=div('',position='absolute',inset='-1px',border='1px dashed '+cy,border_radius='inherit',pointer_events='none')
    return f'<sc-if value="{{{{measure}}}}" hint-placeholder-val="{{{{false}}}}">{h}{pad}{rad}</sc-if>'
def stage():
    tb=row(row(tag('span','Tone',font='600 12.5px Inter, sans-serif',color='var(--muted)')+seg_loop('tones')+tag('span','Size',font='600 12.5px Inter, sans-serif',color='var(--muted)',margin_left='8px')+seg_loop('sizes'),gap='8px',flex_wrap='wrap')
        +row(toggle('Outlined','outlined','toggleOutlined')+toggle('Pill','pill','togglePill')+toggle('Measure','measure','toggleMeasure'),gap='6px',flex_wrap='wrap'),justify_content='space-between',gap='12px',flex_wrap='wrap',padding='10px 12px',border_bottom='1px solid var(--line)',background='var(--surface)')
    btnw=div(tag('button','Save changes',attrs=' type="button" style="{{prevStyle}}"')+measure_overlay(),position='relative',display='inline-flex')
    area=tag('div',btnw,attrs=' class="grid"',background_color='var(--bg)',min_height='240px',display='flex',align_items='center',justify_content='center',padding='48px 24px')
    code=row(tag('code','{{snippet}}',font=f"13.5px {MONO}",color='#E6E9EC',overflow='hidden',text_overflow='ellipsis',white_space='nowrap')+btn(icon('copy',14)+'Copy',kind='ghost',color='#E6E9EC',min_height='34px',font_size='12.5px',padding='6px 10px'),justify_content='space-between',gap='10px',padding='8px 8px 8px 16px',background='var(--term)',border_top='1px solid var(--line)')
    return div(tb+area+code,border='1px solid var(--line)',border_radius='4px',overflow='hidden')
def example(title,desc,prev,src):
    return div(tag('div',prev,attrs=' class="grid"',background_color='var(--bg)',min_height='150px',display='flex',align_items='center',justify_content='center',gap='10px',padding='24px',flex='1 1 240px',border_right='1px solid var(--line)')
        +col(col(txt(title,'h3',font='650 16px Inter, sans-serif')+txt(desc,font_size='14px',color='var(--muted)',line_height='1.55'),gap='4px',padding='16px 18px')
        +pre(src,font='13px/1.6 '+MONO,padding='14px 18px',flex='1'),gap='0',flex='2 1 360px',min_width='0'),border='1px solid var(--line)',border_radius='4px',overflow='hidden',background='var(--surface)',display='flex',flex_wrap='wrap')
def sbtn(t,kind='primary',**k):
    base=dict(font='600 14px Inter, sans-serif',padding='10px 16px',height='44px',border_radius='4px',display='inline-flex',align_items='center',gap='8px',cursor='pointer')
    if kind=='primary': base.update(background='var(--brand)',color='#fff',border='1px solid var(--brand)')
    elif kind=='quiet': base.update(background='var(--surface)',color='var(--ink)',border='1px solid var(--line)')
    base.update(k); return tag('button',t,attrs=' type="button"',**base)
def reference_v2():
    fams=[('Actions',['Button','IconButton','ButtonGroup','Dropdown']),('Layout',['Container','Row','Stack','Grid','Spacer','Divider']),('Navigation',['Navbar','Sidebar','Link','Tabs','Menu']),('Forms',['Input','Select','Checkbox','Switch','Slider','Form'])]
    idx=f'<label style="{st(display="flex",align_items="center",gap="8px",padding="0 10px",min_height="38px",border="1px solid var(--line)",border_radius="4px",background="var(--sunken)",color="var(--muted)",margin_bottom="14px")}">{icon("search",14)}<input type="search" placeholder="Filter 77 built-ins" aria-label="Filter components" style="{st(border="0",background="transparent",font="13.5px Inter, sans-serif",color="var(--ink)",flex="1",min_width="0",outline="none")}"><kbd style="{st(font="11px "+MONO,color="var(--muted)")}">/</kbd></label>'
    for g,xs in fams:
        idx+=row(txt(g,font='600 12.5px Inter, sans-serif',color='var(--muted)')+txt(str(len(xs)),font='12px '+MONO,color='var(--muted)'),justify_content='space-between',margin='14px 0 4px',padding='0 10px')
        for x in xs:
            on=x=='Button'
            idx+=a(x,'#',attrs_current=on,display='block',padding='6px 10px',font_size='14px',font_weight='600' if on else '400',color='var(--ink)' if on else 'var(--muted)',background='var(--surface)' if on else 'transparent',box_shadow='inset 2px 0 0 var(--accent-ink)' if on else 'none',border_radius='0 4px 4px 0' if on else '4px')
    side=tag('nav',idx,attrs=' aria-label="Built-ins"',flex='0 1 232px',min_width='200px',padding='28px 0')
    title=col(row(txt('<a href="#" style="color: var(--muted); text-decoration: none">Reference</a> / Actions',font_size='13px',color='var(--muted)')+row(copymenu(),gap='4px'),justify_content='space-between',flex_wrap='wrap',gap='8px')
        +txt('Button','h1',font='650 44px/1.05 Inter, sans-serif',letter_spacing='-.03em')
        +txt('A control that does something when pressed. What it shows goes in its block; what it does goes in <code>on click</code>.',font_size='17px',line_height='1.6',color='var(--muted)',max_width='640px')
        +wrap(chip('Since 3.0')+chip(icon('check',11)+'Web','accent')+chip(icon('check',11)+'App','accent')+chip('Not in PDF or slides','off')+a('View source','#',font_size='13px',color='var(--brand-ink)',margin_left='4px'),gap='6px'),gap='12px')
    ex=div(example('Submit a form','Inside a Form, type: .submit sends it; every other button never does.',col(div('',width='180px',height='36px',border='1px solid var(--line)',border_radius='4px',background='var(--surface)')+sbtn('Join'),gap='10px',align_items='flex-start'),'Form {\n    Input(bind: email, label: "Email")\n    Button("Join", type: .submit).primary\n}')
        +example('While it saves','An async action is pending while it runs; read it to disable the button.',sbtn('Saving…',opacity='.55',cursor='not-allowed'),'Button("Save", disabled: save.pending)\n    .primary { on click { save() } }')
        +example('A choice of two','A ButtonGroup joins buttons that belong together.',row(sbtn('Day','quiet',border_radius='4px 0 0 4px')+sbtn('Night',border_radius='0 4px 4px 0',margin_left='-1px'),gap='0'),'ButtonGroup {\n    Button("Day")\n    Button("Night").primary\n}'),display='flex',flex_direction='column',gap='14px')
    props=[('label','String','','What the button says. Positional.'),('tone','Tone','.primary','.primary, .secondary, .success, .danger, .warning, .info'),('size','Size','.md','.sm 36px, .md 44px, .lg 52px tall'),('outlined','Bool','false','A border and no fill'),('pill','Bool','false','Fully rounded ends'),('full','Bool','false','Fills the width of its row'),('type','ButtonType','.button','.submit sends the Form it is in'),('disabled','Bool','false','Greys it out and ignores clicks')]
    th=lambda h: f'<th scope="col" style="{st(text_align="left",padding="10px 14px",font="600 12.5px Inter, sans-serif",color="var(--muted)",border_bottom="1px solid var(--line)")}">{h}</th>'
    rows=''.join('<tr>'+f'<td style="{st(padding="11px 14px",border_bottom="1px solid var(--line)",font="500 13px "+MONO,color="var(--ink)",white_space="nowrap")}">{n}</td>'+f'<td style="{st(padding="11px 14px",border_bottom="1px solid var(--line)",white_space="nowrap")}">'+tag('span',E(t),font='500 12px '+MONO,color='var(--brand-ink)',background='var(--brand-subtle)',padding='2px 6px',border_radius='3px')+'</td>'+f'<td style="{st(padding="11px 14px",border_bottom="1px solid var(--line)",font="13px "+MONO,color="var(--muted)",white_space="nowrap")}">{E(d) or "required"}</td>'+f'<td style="{st(padding="11px 14px",border_bottom="1px solid var(--line)",font="14px Inter, sans-serif",color="var(--ink)")}">{E(w)}</td></tr>' for n,t,d,w in props)
    ptab=f'<div style="{st(overflow_x="auto",border="1px solid var(--line)",border_radius="4px",background="var(--surface)")}"><table style="{st(width="100%",border_collapse="collapse")}"><thead><tr>{th("Prop")}{th("Type")}{th("Default")}{th("What it does")}</tr></thead><tbody>{rows}</tbody></table></div>'
    a11y=col(''.join(row(div('',width='6px',height='6px',background='var(--accent-ink)',flex='none',margin_top='9px',border_radius='1px')+txt(t,font_size='15px',line_height='1.6'),gap='12px',align_items='flex-start') for t in ['It renders a real <code>&lt;button type="button"&gt;</code>, so Tab, Enter and Space work with no extra code.','A button needs text a reader can see or hear; one with neither is <a href="Unified-Error.dc.html">A05</a>.','An <code>aria-label</code> must contain the visible words, or voice control cannot find it: <a href="Unified-Error.dc.html">A15</a>.']),gap='10px')
    h2=lambda t,i: txt(t,'h2',attrs=f' id="{i}"',font='650 24px/1.2 Inter, sans-serif',letter_spacing='-.02em',margin='18px 0 0')
    main=tag('article',col(title+stage()+h2('Examples','examples')+ex+h2('Props','props')+ptab+h2('Events','events')+txt('Every DOM event, on its <code>&lt;button&gt;</code>: <code>on click</code>, <code>on focus</code>, <code>on key("mod+s")</code>. A handler written on a component call reaches its root, so a styled button of your own is clickable too.',font_size='15px',line_height='1.65',max_width='680px')+h2('Accessibility','a11y')+a11y,gap='18px'),flex='999 1 560px',min_width='0',padding='28px 0 0')
    rail=tag('aside',col(label('On this page')+''.join(a(t,'#',font_size='13.5px',color='var(--ink)' if i==0 else 'var(--muted)',padding='3px 0 3px 12px',border_left='1px solid '+('var(--accent-ink)' if i==0 else 'var(--line)')) for i,t in enumerate(['Preview','Examples','Props','Events','Accessibility']))
        +div('',height='12px')+label('Composition')+pre('ButtonGroup\n├─ Button\n└─ Button\n\nForm\n└─ Button(type: .submit)',font='12.5px/1.6 '+MONO,padding='12px 14px',border_radius='4px')
        +div('',height='12px')+label('Related')+''.join(a(t,'#',font_size='13.5px',color='var(--brand-ink)') for t in ['IconButton','ButtonGroup','Form','Recipe: disable Save while it runs']),gap='8px'),attrs=' aria-label="On this page"',flex='0 1 220px',min_width='200px',padding='32px 0')
    return header('Reference')+tag('main',div(side+main+rail,display='flex',flex_wrap='wrap',gap='40px',align_items='flex-start'),max_width='1360px',margin='0 auto',padding='0 24px')+footer()
